 b=p.chromium.launch();g=b.new_page();g.goto('http://localhost:8080/');g.evaluate("async()=>{let m=await import('/fps-game.js');window.game=m.mountFPS(document.querySelector('#app'),{exercise:'bandage'})}");g.click('#fpsStart');g.evaluate('game.state.map=Array.from({length:17},(_,y)=>Array.from({length:17},(_,x)=>!x||!y||x===16||y===16?1:0));game.state.x=3.5;game.state.y=4.5;game.state.wounded=true;game.state.bleed=11;game.state.entities=[{kind:"enemy",x:6,y:4.5,hp:2,clock:99}]');g.keyboard.press('f');assert g.evaluate('game.state.bandaging')==0;g.evaluate('game.state.map[4][5]=1');g.keyboard.press('f');assert g.evaluate('game.state.bandaging')>0;a=g.evaluate('game.state.ammo');g.keyboard.press('Space');g.locator('#fpsCanvas').dispatch_event('mousedown',{'button':0});assert g.evaluate('game.state.ammo')==a;old=g.evaluate('game.state.x');g.keyboard.down('w');g.wait_for_timeout(180);g.keyboard.up('w');assert g.evaluate('game.state.x')>old;g.wait_for_timeout(3200);assert not g.evaluate('game.state.wounded');print('PASS real wall cover healing, movement and firing lock');b.close()
